CREATE TABLE `search_documents` (`id` CHAR(36) CHARACTER SET ascii NOT NULL,`organization_id` CHAR(36) CHARACTER SET ascii NOT NULL,`workspace_id` CHAR(36) CHARACTER SET ascii NOT NULL,`resource_type` VARCHAR(64) NOT NULL,`resource_id` CHAR(36) CHARACTER SET ascii NOT NULL,`title` VARCHAR(255) NOT NULL,`subtitle` VARCHAR(500) NULL,`route` VARCHAR(500) NOT NULL,`required_capability` VARCHAR(128) CHARACTER SET ascii NOT NULL,`source_version` BIGINT UNSIGNED NOT NULL,`updated_at` DATETIME(3) NOT NULL,PRIMARY KEY (`id`),UNIQUE KEY `uq_search_resource` (`organization_id`,`workspace_id`,`resource_type`,`resource_id`),KEY `idx_search_scope_time` (`organization_id`,`workspace_id`,`updated_at`,`id`),KEY `idx_search_capability` (`organization_id`,`workspace_id`,`required_capability`),CONSTRAINT `fk_search_org` FOREIGN KEY (`organization_id`) REFERENCES `organizations` (`id`) ON DELETE CASCADE,CONSTRAINT `fk_search_workspace` FOREIGN KEY (`workspace_id`) REFERENCES `workspaces` (`id`) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
